/* it translations part 1/7 — early civilizations & antiquity */
Object.assign(window.DATA_IT, {
  sumer_writing: { n: 'Invenzione della scrittura cuneiforme', p: 'Uruk, Sumer', d: 'I Sumeri di Uruk sviluppano la scrittura cuneiforme — il più antico sistema di scrittura conosciuto al mondo — e con essa ha inizio la storia registrata.' },
  egypt_unify: { n: 'Unificazione dell’Egitto', p: 'Menfi, Egitto', d: 'Narmer unifica l’Alto e il Basso Egitto, fondando uno degli stati più longevi della storia mondiale.' },
  indus_civ: { n: 'Civiltà della valle dell’Indo', p: 'Mohenjo-daro, valle dell’Indo', d: 'Nella valle dell’Indo fioriscono città a pianta regolare, con fognature e pesi standardizzati — urbane quanto l’Egitto o Sumer, e ancora in gran parte indecifrate.' },
  trypillia: { n: 'I giganteschi insediamenti tripoliani', p: 'Talianky, Ucraina', d: 'Gli agricoltori Cucuteni-Trypillia dell’odierna Ucraina costruiscono i più grandi insediamenti della Terra del loro tempo — Talianky ospitava forse 15 000 persone su centinaia di ettari, 5 000 anni prima di Kyiv.' },
  giza_pyramid: { n: 'Costruzione della Grande Piramide di Giza', p: 'Giza, Egitto', d: 'La piramide di Cheope — 146 metri d’altezza, la struttura umana più alta per 3 800 anni — sorge sulla sponda occidentale del Nilo.' },
  stonehenge: { n: 'Stonehenge completato', p: 'Stonehenge, Britannia', d: 'I costruttori neolitici innalzano i grandi triliti di sarsen sulla piana di Salisbury, orientandoli verso l’alba del solstizio d’estate — contemporanei dei costruttori di piramidi.' },
  caral: { n: 'Civiltà di Caral-Supe', p: 'Caral, Perù', d: 'La più antica città conosciuta delle Americhe fiorisce sulla costa peruviana con piramidi monumentali — niente ceramica, nessuna traccia di guerra, e registri simili a quipu.' },
  akkad: { n: 'Impero akkadico — il primo impero', p: 'Akkad, Mesopotamia', d: 'Sargon di Akkad forgia il primo impero multietnico della storia, che si estende dal Golfo Persico al Mediterraneo.' },
  gilgamesh: { n: 'Epopea di Gilgamesh', p: 'Uruk, Mesopotamia', d: 'La più antica grande letteratura giunta fino a noi viene composta in sumero, e racconta la ricerca dell’immortalità da parte di un re.' },
  shang: { n: 'Dinastia Shang', p: 'Anyang, Cina', d: 'La prima dinastia cinese confermata dall’archeologia, celebre per la fusione del bronzo e per la scrittura su ossi oracolari — l’antenata della scrittura cinese.' },
  minoan: { n: 'Civiltà minoica', p: 'Cnosso, Creta', d: 'La prima grande civiltà d’Europa domina l’Egeo dal palazzo di Cnosso, con affreschi vivaci e una scrittura ancora indecifrata.' },
  hammurabi: { n: 'Codice di Hammurabi', p: 'Babilonia', d: 'Hammurabi promulga uno dei più antichi codici legali decifrati: 282 leggi incise su una stele di pietra — «occhio per occhio».' },
  bronze_collapse: { n: 'Crollo della tarda età del Bronzo', p: 'Mediterraneo orientale', d: 'In pochi decenni collassano le economie palaziali da Micene a Ugarit — siccità, carestie, terremoti e i misteriosi «Popoli del Mare».' },
  troy: { n: 'Guerra di Troia (data tradizionale)', p: 'Troia, Anatolia', d: 'Leggenda e archeologia si fondono: una guerra per Elena di Troia, poi resa immortale da Omero, proprio mentre il mondo del Bronzo stava sfaldandosi.' },
  phoenician_alpha: { n: 'Alfabeto fenicio', p: 'Byblos, Fenicia', d: 'I mercanti fenici creano un alfabeto consonantico di 22 lettere — l’antenato del greco, del latino, dell’arabo, dell’ebraico e della maggior parte degli alfabeti in uso oggi.' },
  david: { n: 'La Gerusalemme del re Davide', p: 'Gerusalemme', d: 'Secondo la Bibbia, Davide conquista Gerusalemme e ne fa la capitale di un regno d’Israele unito.' },
  kush: { n: 'Regno di Kush', p: 'Meroë, Nubia', d: 'Il regno nubiano di Kush domina il corso superiore del Nilo per oltre un millennio — a volte conquistando l’Egitto stesso — e costruisce le proprie piramidi a Meroë.' },
  olmec: { n: 'Civiltà olmeca', p: 'La Venta, Messico', d: 'La «cultura madre» della Mesoamerica scolpisce colossali teste di pietra e getta le basi di rituali che i Maya e gli Aztechi erediteranno.' },
  zhou: { n: 'Dinastia Zhou', p: 'Haojing, Cina', d: 'La dinastia cinese più longeva introduce il «Mandato del Cielo», mentre i suoi ultimi secoli producono Confucio, Laozi e le Cento Scuole di pensiero.' },
  assyria: { n: 'Impero neoassiro', p: 'Ninive, Assiria', d: 'La prima vera superpotenza: eserciti di ferro, deportazioni di massa e la grande biblioteca di Assurbanipal fanno dell’Assiria la padrona del Medio Oriente.' },
  new_kingdom_ramses: { n: 'Ramses II', p: 'Tebe, Egitto', d: 'Il più grande faraone d’Egitto regna 66 anni, combatte gli Ittiti a Qadesh e fa costruire Abu Simbel.' },
  olympics: { n: 'I primi Giochi olimpici', p: 'Olimpia, Grecia', d: 'Le città-stato greche sospendono le guerre ogni quattro anni, mentre gli atleti gareggiano nudi a Olimpia in onore di Zeus.' },
  rome_founded: { n: 'Fondazione di Roma', p: 'Roma', d: 'La data tradizionale della fondazione di Roma da parte di Romolo sul colle Palatino — un villaggio destinato a dominare il mondo mediterraneo.' },
  homer: { n: 'Omero compone l’Iliade e l’Odissea', p: 'Ionia (Smirne)', d: 'Un aedo cieco o una tradizione di cantori — in ogni caso, la pietra angolare della letteratura occidentale viene posata sulla costa dell’Asia Minore.' },
  scythia: { n: 'Il regno scitico', p: 'Steppa del basso Dnipro, Ucraina', d: 'I nomadi a cavallo intervistati da Erodoto dominano la steppa ucraina e vendono grano ad Atene; dai loro kurgan reali emergono ancora capolavori d’oro come la celebre pectorale.' },
  buddha: { n: 'Siddhartha Gautama — il Buddha', p: 'Bodh Gaya, India', d: 'Un principe del clan Shakya raggiunge l’illuminazione sotto l’albero Bodhi e insegna la Via di mezzo, fondando una delle grandi religioni del mondo.' },
  confucius: { n: 'Confucio', p: 'Qufu, Cina', d: 'Il pensatore più influente della Cina insegna un’etica di lealtà familiare, rituale e governo benevolo — le sue idee modellano l’Asia orientale ancora oggi.' },
  achaemenid: { n: 'Impero persiano achemenide', p: 'Persepoli, Persia', d: 'Ciro il Grande fonda l’impero più vasto mai visto fino ad allora; i suoi successori costruiscono Persepoli e tollerano le religioni locali — incluso il ritorno degli ebrei a Gerusalemme.' },
  temple_destroyed: { n: 'Nabucodonosor distrugge Gerusalemme', p: 'Gerusalemme', d: 'Gli eserciti babilonesi incendiano il Tempio di Salomone e deportano l’élite giudea a Babilonia — la cattività babilonese.' },
  solon: { n: 'Le riforme di Solone', p: 'Atene', d: 'Il legislatore ateniese abolisce la schiavitù per debiti e getta le basi costituzionali della democrazia.' },
  marathon: { n: 'Battaglia di Maratona', p: 'Maratona, Grecia', d: 'Gli opliti ateniesi respingono la prima invasione persiana; la leggendaria corsa del messaggero Fidippide dà il nome alla maratona.' },
  salamis: { n: 'Il culmine delle guerre persiane', p: 'Termopili e Salamina', d: 'I 300 di Leonida cadono alle Termopili, poi la flotta greca distrugge quella di Serse a Salamina — la Grecia classica è salvata.' },
  bosporan: { n: 'Regno del Bosforo', p: 'Panticapeo (Kerč)', d: 'Un regno di sovrani greci esteso su entrambe le rive dello stretto di Kerč diventa il cliente più orientale di Roma — e la grande arteria del commercio tra la steppa e il Mar Nero.' },
  warring_states: { n: 'Il periodo dei Regni Combattenti', p: 'Cina', d: 'Sette regni cinesi si combattono per 250 anni in una guerra di annientamento, alimentando una corsa agli armamenti di filosofia, tattica e tecnologia — dalla quale emergeranno i Qin.' },
  socrates: { n: 'Socrate', p: 'Atene', d: 'Il tafano di Atene mette in discussione tutto, viene processato per «corruzione dei giovani» e muore bevendo la cicuta — insegnando filosofia con l’esempio.' },
  plato: { n: 'Platone', p: 'Atene', d: 'L’allievo di Socrate fonda l’Accademia — il prototipo dell’università — e scrive dialoghi che orientano il pensiero occidentale da 2 400 anni.' },
  chersonesus: { n: 'Fondazione di Chersoneso', p: 'Chersoneso (Sebastopoli)', d: 'Coloni greci provenienti da Heraclea Pontica fondano una polis democratica sulla costa sud-occidentale della Crimea; essa coltiverà quella riva per due millenni e batterà moneta propria.' },
  aristotle: { n: 'Aristotele', p: 'Atene e Pella', d: 'Precettore di Alessandro e fondatore del Liceo, sistematizza logica, biologia, etica e politica — «il maestro di chi sa».' },
  alexander: { n: 'Alessandro Magno', p: 'Pella, Macedonia', d: 'In 13 anni il giovane macedone conquista un territorio che va dalla Grecia all’India, diffonde la cultura ellenistica e muore a 32 anni a Babilonia.' },
  hellenistic: { n: 'Le conquiste di Alessandro Magno', p: 'Macedonia → India', d: 'Lingua, arte e scienza greche si fondono con l’Oriente dal Nilo all’Indo, gettando i semi del mondo ellenistico.' },
  euclid: { n: 'Gli Elementi di Euclide', p: 'Alessandria', d: 'Il più influente libro di testo mai scritto sistematizza la geometria a partire da cinque assiomi — in uso ancora nel XX secolo.' },
  library_alexandria: { n: 'La Biblioteca di Alessandria', p: 'Alessandria d’Egitto', d: 'I Tolomei cercano di raccogliere tutti i libri del mondo; la grande biblioteca fa di Alessandria la capitale scientifica del Mediterraneo per secoli.' },
  maurya: { n: 'Impero Maurya', p: 'Pataliputra, India', d: 'Chandragupta Maurya unisce per la prima volta gran parte dell’Asia meridionale; il suo ministro Chanakya scrive il machiavellico Arthashastra — 1 700 anni in anticipo.' },
  ashoka: { n: 'Ashoka il Grande', p: 'Pataliputra, India', d: 'Dopo la strage di Kalinga, il più grande imperatore dell’India abbraccia il buddhismo e fa incidere editti di tolleranza religiosa in tutto il subcontinente.' },
  kalinga: { n: 'Ashoka abbraccia il buddhismo', p: 'Kalinga, India', d: 'Sconvolto dalla propria sanguinosa conquista di Kalinga, Ashoka si converte al buddhismo e sponsorizza missionari fino in Egitto e in Grecia.' },
  punic1: { n: 'Prima guerra punica', p: 'Sicilia', d: 'Roma e Cartagine si contendono la Sicilia per 23 anni; Roma costruisce la sua prima vera flotta e conquista la sua prima provincia.' },
  qin_shi_huang: { n: 'Qin Shi Huang', p: 'Xianyang, Cina', d: 'Il Primo Imperatore della Cina chiude l’era dei Regni Combattenti, standardizza scrittura, pesi e larghezza degli assi — e viene sepolto insieme all’Esercito di terracotta.' },
  qin_unify: { n: 'Unificazione della Cina', p: 'Xianyang, Cina', d: '«Tutto ciò che sta sotto il cielo» è unito sotto un solo imperatore — l’inizio di 2 000 anni di Cina imperiale.' },
  terracotta: { n: 'L’Esercito di terracotta', p: 'Xi’an, Cina', d: 'Migliaia di soldati di terracotta, tutti diversi e a grandezza naturale, vegliano sulla tomba del Primo Imperatore — scoperti da contadini che scavavano un pozzo nel 1974.' },
  great_wall: { n: 'Inizio della Grande Muraglia', p: 'Cina settentrionale', d: 'Gli ingegneri Qin collegano fortificazioni più antiche in un’unica «muraglia di 10 000 li» contro i razziatori nomadi.' },
  punic2: { n: 'Seconda guerra punica — Annibale', p: 'Alpi e Italia', d: 'Annibale porta gli elefanti da guerra oltre le Alpi e devasta l’Italia per 15 anni, schiacciando Roma a Canne — ma alla fine sarà Cartagine a perdere.' },
  archimedes: { n: 'Archimede', p: 'Siracusa, Sicilia', d: 'Il più grande matematico dell’antichità calcola π, la spinta («Eureka!») e le leve — ucciso da un soldato romano mentre disegnava figure geometriche.' },
  silk_road: { n: 'Apertura della Via della Seta', p: 'Chang’an, Cina', d: 'Le missioni verso occidente di Zhang Qian aprono la rete carovanaria di 7 000 km che collega Cina, Asia centrale, India, Persia e Roma.' },
  han: { n: 'Dinastia Han', p: 'Luoyang, Cina', d: 'Il grande contemporaneo orientale di Roma: si inventa la carta, il confucianesimo diventa ideologia di stato — e i cinesi han chiamano ancora se stessi «han».' },
  punic3: { n: 'Distruzione di Cartagine', p: 'Cartagine', d: 'Roma rade al suolo la rivale e semina sale tra le macerie (così dice la leggenda), diventando la padrona indiscussa del Mediterraneo.' },
  spartacus: { n: 'La rivolta degli schiavi di Spartaco', p: 'Campania, Italia', d: 'Un gladiatore trace guida 70 000 schiavi fuggiti su e giù per l’Italia, sconfiggendo legione dopo legione, prima delle crocifissioni finali lungo la Via Appia.' },
  caesar: { n: 'Giulio Cesare', p: 'Roma', d: 'Conquistatore della Gallia, attraversatore del Rubicone, dittatore a vita — assassinato alle Idi di marzo da senatori che temevano un re.' },
  gaul: { n: 'Cesare conquista la Gallia', p: 'Gallia', d: '«Gallia est omnis divisa in partes tres» — otto anni di strage e di un geniale commentario di guerra, e la Gallia diventa romana.' },
  cleopatra: { n: 'Cleopatra VII', p: 'Alessandria d’Egitto', d: 'L’ultima faraona d’Egitto — capace di parlare nove lingue — seduce Cesare e Antonio nel tentativo disperato di salvare il suo regno da Roma.' },
  actium: { n: 'Battaglia di Azio', p: 'Azio, Grecia', d: 'Ottaviano sconfigge Antonio e Cleopatra; cadono gli ultimi rivali della Repubblica e comincia una nuova età di imperatori.' },
  augustus: { n: 'Augusto — il primo imperatore', p: 'Roma', d: 'Ottaviano diventa «Augusto» e trasforma Roma in un impero; seguono la pace, il marmo e la Pax Romana.' },
  roman_empire: { n: 'Impero romano', p: 'Roma', d: 'All’apogeo sotto Traiano, Roma governa dalla Britannia al Golfo Persico — 70 milioni di persone, un’unica legge, strade che esistono ancora oggi.' },
  jesus: { n: 'Gesù di Nazareth', p: 'Giudea', d: 'Un predicatore galileo crocifisso da Roma diventa il centro della più grande religione del mondo; i suoi seguaci dividono la storia in due ere.' },
  fire_rome: { n: 'Il grande incendio di Roma', p: 'Roma', d: 'Sei giorni di fuoco divorano la città; la voce pubblica incolpa Nerone, che incolpa i cristiani.' },
  colosseum: { n: 'Costruzione del Colosseo', p: 'Roma', d: 'L’anfiteatro da 50 000 posti apre con 100 giorni di giochi — ingegneria romana e crudeltà romana in un solo monumento.' },
  vesuvius: { n: 'Il Vesuvio erutta', p: 'Pompei, Italia', d: 'Le colate piroclastiche seppelliscono Pompei ed Ercolano, congelando nel tempo una città romana — e Plinio il Vecchio.' },
  pax_romana: { n: 'Pax Romana', p: 'Roma', d: 'Due secoli di pace relativa, commercio e stabilità da Augusto a Marco Aurelio — il Mediterraneo come unico mondo connesso.' },
  hadrian_wall: { n: 'Il vallo di Adriano', p: 'Britannia settentrionale', d: 'Roma mura il confine del proprio impero con 117 km di pietra attraverso la Britannia settentrionale.' },
  paper: { n: 'Invenzione della carta', p: 'Luoyang, Cina', d: 'L’ufficiale di corte Cai Lun perfeziona la produzione della carta — la tecnologia dell’informazione che porterà la burocrazia cinese, la scienza araba e le stampe di Gutenberg.' },
  three_kingdoms: { n: 'Il periodo dei Tre Regni', p: 'Luoyang, Cina', d: 'La Cina Han si divide in Wei, Shu e Wu; l’epoca di Cao Cao e Zhuge Liang diventa l’epopea nazionale cinese.' },
  constantinople_founded: { n: 'Fondazione di Costantinopoli', p: 'Bizanzio', d: 'Costantino ridedica Bizanzio come propria capitale — presto la città cristiana più grande e ricca della Terra.' },
  nicaea: { n: 'Primo concilio di Nicea', p: 'Nicea', d: '318 vescovi definiscono il Credo niceno — il cristianesimo ha la sua prima dottrina uniforme.' },
  thessalonica: { n: 'Il cristianesimo diventa religione di Stato di Roma', p: 'Salonicco', d: 'L’editto di Tessalonica fa della fede nicena la religione ufficiale dell’impero, vietando i culti pagani.' },
  attila: { n: 'Attila re degli Unni', p: 'Pannonia', d: 'Il «flagello di Dio» estorce e brucia da Costantinopoli alla Gallia, finché il suo impero non muore con lui.' },
  rome_falls: { n: 'Caduta dell’Impero romano d’Occidente', p: 'Ravenna', d: 'Odoacre depone l’ultimo imperatore d’Occidente — la fine convenzionale dell’antichità in Occidente.' },
  gupta: { n: 'Impero Gupta', p: 'Pataliputra, India', d: 'L’età dell’oro classica dell’India: la poesia di Kalidasa, il Kama Sutra, la matematica decimale e il concetto di zero.' },
  aryabhata: { n: 'Aryabhata', p: 'Kusumapura, India', d: 'Calcola π con quattro decimali, la rotazione della Terra e la durata dell’anno con sorprendente precisione — a 23 anni.' },
  maya_classic: { n: 'Il periodo classico dei Maya', p: 'Tikal, Guatemala', d: 'Le città-stato di templi a piramide e scrittura geroglifica raggiungono l’apice, con Tikal e Calakmul come superpotenze rivali.' },
  teotihuacan: { n: 'Teotihuacan', p: 'Teotihuacan, Messico', d: 'La prima metropoli delle Americhe — oltre 100 000 persone lungo il Viale dei Morti — esporta arte, dèi e influenza in tutta la Mesoamerica.' },
  aksum: { n: 'Il regno di Aksum', p: 'Aksum, Etiopia', d: 'L’impero commerciale del Corno d’Africa emette moneta d’oro propria, adotta il cristianesimo (verso il 330) e rivendica l’eredità della Regina di Saba.' },
});

