  charlemagne_crowned: { n: 'Carlo Magno incoronato imperatore', p: 'Roma', d: 'Papa Leone III incorona Carlo Magno in San Pietro — riportando in Occidente l’idea imperiale e suscitando l’ira di Costantinopoli.' },
  baghdad_founded: { n: 'Fondazione di Baghdad', p: 'Baghdad', d: 'La città rotonda di al-Mansur diventa la capitale intellettuale del mondo nel giro di una generazione.' },
