  decolonization_africa: { n: 'La decolonizzazione dell’Africa', p: 'Accra, Ghana', d: 'Il Ghana apre la strada; nel giro di due decenni la maggior parte dell’Africa è libera — «cercate prima il regno politico», disse Nkrumah.' },
  sputnik: { n: 'Lancio dello Sputnik', p: 'Tyuratam, URSS', d: 'Una sfera di metallo di 58 cm cicala sopra le teste — comincia l’era spaziale, e l’America, presa dal panico, crea la NASA.' },
  gagarin: { n: 'Gagarin orbita attorno alla Terra', p: 'Baikonur', d: '«Poehali!» — 108 minuti che fanno di Jurij Gagarin il primo essere umano nello spazio, per sempre.' },
  everest: { n: 'La prima ascensione dell’Everest', p: 'Monte Everest', d: 'Hillary e Tenzing in cima al mondo il 29 maggio 1953 — la notizia giunge a Londra il giorno dell’incoronazione.' },
