  mlk_speech: { n: '«I have a dream»', p: 'Washington, D.C.', d: 'Un quarto di milione di persone marcia su Washington; dai gradini del memoriale di Lincoln, il sogno di King entra nella storia.' },
  mlk: { n: 'Martin Luther King Jr.', p: 'Atlanta, USA', d: 'La nonviolenza come strategia e come sermone — la voce del movimento per i diritti civili, premiata con il Nobel, assassinata a 39 anni.' },
  vietnam_war: { n: 'Guerra del Vietnam', p: 'Vietnam', d: 'Venti anni di guerra si chiudono con gli elicotteri che decollano dal tetto dell’ambasciata a Saigon — la prima guerra persa in televisione.' },
  apollo11: { n: 'Apollo 11 sbarca sulla Luna', p: 'Da Cape Canaveral alla Luna', d: '«L’Aquila è atterrata.» Armstrong e Aldrin camminano su un altro mondo davanti a 600 milioni di spettatori — «un balzo gigante per l’umanità».' },
  berlin_wall: { n: 'La caduta del muro di Berlino', p: 'Berlino', d: 'Una conferenza stampa goffa, poi i martelli: il Muro si apre, e il simbolo più tangibile della guerra fredda si sbriciola.' },
  singing_revolution: { n: 'La Rivoluzione cantata e la Via Baltica', p: 'Da Tallinn a Riga a Vilnius', d: 'Centinaia di migliaia di persone cantano all’unisono canzoni proibite — e il 23 agosto 1989 due milioni di persone si tengono per mano lungo 675 km da Tallinn a Vilnius. La Lituania dichiara per prima la restaurazione dell’indipendenza (11 marzo 1990); nell’agosto 1991 tutte e tre sono libere.' },
